module.exports = [
{ e: "🧠", art: { b: "🧠", s: ["❤️", "⚡", "🐟", "🦵"], c: ["#4E0B2A", "#C22C6A"] },
pt: { h: "No médico, Leo viu uma máquina desenhando linhas em zigue-zague enquanto ouvia o coração do vovô. “O seu coração está desenhando?”, perguntou. “Mais ou menos”, riu o vovô. “Ele funciona com eletricidade! E o nosso cérebro também.”", t: "A eletricidade do nosso corpo", f: "O cérebro conversa com o corpo por meio de sinais elétricos minúsculos que correm pelos nervos. O coração também tem um “marca-passo” natural que manda um choquinho elétrico a cada batida. A máquina do médico, o eletrocardiograma, desenha esses sinais.", x: "No rio Amazonas vive o poraquê, um peixe elétrico que pode dar descargas de mais de 800 volts, mais que qualquer outro animal conhecido! Ele usa isso para caçar e se defender.", s: ["Os sinais nos nervos podem viajar a mais de 400 quilômetros por hora.", "Apesar do apelido de “enguia elétrica”, o poraquê não é uma enguia: é um peixe parente dos peixes-faca.", "A eletricidade do corpo é muito fraquinha, milhares de vezes menor que a de uma tomada."], ex: { t: "Teste do reflexo do joelho", m: "uma cadeira alta, a lateral da mão de um ajudante", p: ["Sente-se numa cadeira alta, com as pernas soltas, balançando livres.", "O ajudante dá um toque leve, com a lateral da mão, logo abaixo do joelho.", "A perna chuta sozinha! O sinal elétrico vai e volta pela medula tão rápido que você nem precisa pensar."] }, at: "Mapa dos nervos", m: "papel grande, lápis de cor", p: ["Peça para alguém contornar o seu corpo deitado num papel grande.", "Desenhe o cérebro e linhas saindo dele até as mãos e os pés, como fios elétricos.", "Desenhe o coração com um raiozinho e pinte a 11ª lâmpada do painel."], q: "Que coisa você faz tão rápido que nem dá tempo de pensar?" },
en: { h: "At the doctor's, Leo saw a machine drawing zigzag lines while it listened to Grandpa's heart. “Is your heart drawing?” he asked. “Sort of,” Grandpa laughed. “It runs on electricity! And so does our brain.”", t: "The electricity in our bodies", f: "The brain talks to the body using tiny electrical signals that race along the nerves. The heart also has a natural “pacemaker” that sends a little electric pulse with every beat. The doctor's machine, an electrocardiogram, draws those signals.", x: "In the Amazon lives the electric eel, a fish that can deliver shocks of more than 800 volts, more than any other known animal! It uses them to hunt and defend itself.", s: ["Signals in the nerves can travel faster than 400 kilometers per hour (250 mph).", "Despite its name, the electric eel isn't really an eel: it's a fish related to knifefish.", "The body's electricity is very weak, thousands of times weaker than an outlet's."], ex: { t: "Knee reflex test", m: "a tall chair, the side of a helper's hand", p: ["Sit on a tall chair with your legs dangling freely.", "The helper gives a light tap with the side of their hand just below your knee.", "Your leg kicks by itself! The electrical signal goes to your spinal cord and back so fast you don't even have to think."] }, at: "Nerve map", m: "large paper, colored pencils", p: ["Ask someone to trace around your body as you lie on a big sheet of paper.", "Draw the brain and lines running from it to your hands and feet, like electric wires.", "Draw the heart with a little lightning bolt and color the 11th bulb on your chart."], q: "What do you do so fast that there's no time to think?" },
es: { h: "En el médico, Leo vio una máquina dibujando líneas en zigzag mientras escuchaba el corazón del abuelo. “¿Tu corazón está dibujando?”, preguntó. “Más o menos”, se rió el abuelo. “¡Funciona con electricidad! Y nuestro cerebro también.”", t: "La electricidad de nuestro cuerpo", f: "El cerebro habla con el cuerpo mediante señales eléctricas diminutas que corren por los nervios. El corazón también tiene un “marcapasos” natural que manda una pequeña descarga eléctrica en cada latido. La máquina del médico, el electrocardiograma, dibuja esas señales.", x: "¡En el río Amazonas vive la anguila eléctrica, un pez que puede dar descargas de más de 800 voltios, más que cualquier otro animal conocido! La usa para cazar y defenderse.", s: ["Las señales de los nervios pueden viajar a más de 400 kilómetros por hora.", "A pesar de su nombre, la anguila eléctrica no es una anguila: es un pez pariente de los peces cuchillo.", "La electricidad del cuerpo es muy débil, miles de veces menor que la de un enchufe."], ex: { t: "Prueba del reflejo de la rodilla", m: "una silla alta, el costado de la mano de un ayudante", p: ["Siéntate en una silla alta, con las piernas colgando libres.", "El ayudante da un golpecito suave, con el costado de la mano, justo debajo de la rodilla.", "¡La pierna patea sola! La señal eléctrica va y vuelve por la médula tan rápido que ni necesitas pensar."] }, at: "Mapa de los nervios", m: "papel grande, lápices de colores", p: ["Pide a alguien que dibuje el contorno de tu cuerpo acostado sobre un papel grande.", "Dibuja el cerebro y líneas que salen de él hasta las manos y los pies, como cables eléctricos.", "Dibuja el corazón con un rayito y pinta la bombilla 11 del panel."], q: "¿Qué cosa haces tan rápido que ni da tiempo de pensar?" } },

{ e: "💡", art: { b: "💡", s: ["🕯️", "🔦", "🌟", "🏠"], c: ["#4E3A0B", "#E0B02C"] },
pt: { h: "O vovô trocou uma lâmpada antiga e redonda por uma de LED. “Essa nova quase não esquenta e gasta muito menos”, explicou. Nina quis saber como era a vida antes das lâmpadas. “Velas, lampiões a óleo e muita escuridão”, respondeu ele.", t: "A lâmpada", f: "Antes da eletricidade, as casas eram iluminadas por velas e lampiões. No fim dos anos 1870, Thomas Edison, nos Estados Unidos, e Joseph Swan, na Inglaterra, criaram lâmpadas elétricas práticas. Elas tinham um fio fininho, o filamento, que brilhava quando a eletricidade passava.", x: "Numa estação de bombeiros na Califórnia, uma lâmpada está acesa quase sem parar desde 1901! Ela é chamada de Lâmpada Centenária.", s: ["Nas lâmpadas antigas, quase toda a energia virava calor em vez de luz.", "As lâmpadas de LED gastam bem menos energia e duram muitas vezes mais.", "LED quer dizer “diodo emissor de luz”, uma pecinha que brilha sem precisar esquentar um fio."], ex: { t: "Luz que esquenta e luz que não esquenta", m: "uma lâmpada antiga acesa (se tiver), uma lâmpada de LED acesa, um adulto", p: ["Com um adulto, acenda as duas lâmpadas por alguns minutos.", "Aproxime a palma da mão de cada uma, a uns 10 centímetros, sem encostar nunca.", "Qual parece mais quente? A antiga desperdiça energia em calor. Se não tiver uma antiga, compare o LED com o calor de uma panela no fogão, de longe."] }, at: "Linha do tempo da luz", m: "papel comprido, lápis de cor", p: ["Desenhe em ordem: fogueira, vela, lampião, lâmpada antiga e lâmpada de LED.", "Escreva embaixo de cada uma uma vantagem e um problema.", "Pinte a 12ª lâmpada do painel."], q: "Como você acha que era fazer a lição de casa à luz de vela?" },
en: { h: "Grandpa swapped an old round light bulb for an LED one. “This new one barely gets warm and uses much less energy,” he explained. Nina wanted to know what life was like before light bulbs. “Candles, oil lamps and lots of darkness,” he answered.", t: "The light bulb", f: "Before electricity, homes were lit by candles and lamps. In the late 1870s, Thomas Edison in the United States and Joseph Swan in England created practical electric light bulbs. They had a very thin wire, the filament, that glowed when electricity passed through it.", x: "At a fire station in California, one light bulb has been glowing almost nonstop since 1901! It's called the Centennial Light.", s: ["In old bulbs, almost all the energy became heat instead of light.", "LED bulbs use much less energy and last many times longer.", "LED stands for “light-emitting diode,” a tiny part that shines without heating a wire."], ex: { t: "Hot light and cool light", m: "an old-style bulb switched on (if you have one), an LED bulb switched on, a grown-up", p: ["With a grown-up, switch on both bulbs for a few minutes.", "Hold your palm near each one, about 10 cm (4 inches) away, never touching.", "Which feels warmer? The old one wastes energy as heat. If you don't have an old bulb, compare the LED with the warmth of a pot on the stove, from a distance."] }, at: "Timeline of light", m: "long paper, colored pencils", p: ["Draw in order: a campfire, a candle, an oil lamp, an old bulb and an LED bulb.", "Under each one, write one advantage and one problem.", "Color the 12th bulb on your chart."], q: "What do you think it was like to do homework by candlelight?" },
es: { h: "El abuelo cambió una bombilla antigua y redonda por una de LED. “Esta nueva casi no se calienta y gasta mucho menos”, explicó. Nina quiso saber cómo era la vida antes de las bombillas. “Velas, lámparas de aceite y mucha oscuridad”, respondió él.", t: "La bombilla", f: "Antes de la electricidad, las casas se iluminaban con velas y lámparas. A fines de la década de 1870, Thomas Edison, en Estados Unidos, y Joseph Swan, en Inglaterra, crearon bombillas eléctricas prácticas. Tenían un hilo finito, el filamento, que brillaba cuando pasaba la electricidad.", x: "¡En una estación de bomberos de California, hay una bombilla encendida casi sin parar desde 1901! Se llama la Bombilla Centenaria.", s: ["En las bombillas antiguas, casi toda la energía se convertía en calor en vez de luz.", "Las bombillas de LED gastan mucha menos energía y duran muchas veces más.", "LED quiere decir “diodo emisor de luz”, una piecita que brilla sin necesidad de calentar un hilo."], ex: { t: "Luz que calienta y luz que no", m: "una bombilla antigua encendida (si tienes), una bombilla de LED encendida, un adulto", p: ["Con un adulto, enciende las dos bombillas durante unos minutos.", "Acerca la palma de la mano a cada una, a unos 10 centímetros, sin tocarla nunca.", "¿Cuál parece más caliente? La antigua desperdicia energía en calor. Si no tienes una antigua, compara el LED con el calor de una olla en la cocina, de lejos."] }, at: "Línea de tiempo de la luz", m: "papel largo, lápices de colores", p: ["Dibuja en orden: fogata, vela, lámpara de aceite, bombilla antigua y bombilla de LED.", "Debajo de cada una escribe una ventaja y un problema.", "Pinta la bombilla 12 del panel."], q: "¿Cómo crees que era hacer la tarea a la luz de una vela?" } },

{ e: "💧", art: { b: "💧", s: ["🏞️", "⚙️", "🧲", "🔌"], c: ["#0B3A5A", "#2C8AC2"] },
pt: { h: "Na viagem de carro, eles passaram perto de uma barragem enorme, com água caindo com força. “É uma usina hidrelétrica”, contou o vovô. “Quase toda a eletricidade da nossa casa começa assim: com água girando uma roda gigante.” Leo arregalou os olhos: “Água vira luz?”", t: "De onde vem a eletricidade", f: "Em 1831, Michael Faraday descobriu que, quando um ímã gira perto de um fio enrolado, aparece eletricidade no fio. É assim que funciona um gerador. Nas usinas hidrelétricas, a água de um rio represado gira turbinas, que giram geradores enormes.", x: "A usina de Itaipu, no rio Paraná, entre o Brasil e o Paraguai, é uma das que mais produzem energia no mundo! A maior parte da eletricidade do Brasil vem da força da água.", s: ["Existem outras formas de girar geradores: com vapor, com vento ou com o movimento das marés.", "Faraday era um menino pobre que trabalhava encadernando livros e aprendeu ciência lendo os livros que encadernava.", "As barragens produzem energia sem queimar combustível, mas alagam terras e mudam a vida dos rios, dos animais e das pessoas que moram perto."], ex: { t: "Roda d'água", m: "um prato de papelão ou isopor, copinhos de café de papel ou plástico, um lápis, fita, uma torneira ou jarra de água", p: ["Cole os copinhos em volta da borda do prato, todos virados para o mesmo lado, como as pás de uma roda.", "Espete o lápis no centro do prato, como um eixo, e segure pelas pontas.", "Despeje água sobre os copinhos: a roda gira! Nas usinas, essa força gira um gerador e vira eletricidade."] }, at: "Caminho da água até a luz", m: "papel, lápis de cor", p: ["Desenhe um rio, uma barragem, uma turbina girando e fios saindo da usina.", "Desenhe os fios chegando até a sua casa e acendendo uma lâmpada.", "Pinte a 13ª lâmpada do painel."], q: "Por que você acha que a gente deve economizar energia, mesmo vindo da água?" },
en: { h: "On a road trip, they drove past a huge dam with water pouring down hard. “It's a hydroelectric plant,” Grandpa said. “Almost all the electricity in our house starts like this: with water spinning a giant wheel.” Leo's eyes went wide: “Water turns into light?”", t: "Where electricity comes from", f: "In 1831, Michael Faraday discovered that when a magnet spins near a coil of wire, electricity appears in the wire. That's how a generator works. In hydroelectric plants, water from a dammed river spins turbines, which turn enormous generators.", x: "The Itaipu power plant, on the Paraná River between Brazil and Paraguay, is one of the biggest energy producers in the world! Most of Brazil's electricity comes from the power of water.", s: ["There are other ways to spin generators: with steam, with wind or with the movement of the tides.", "Faraday was a poor boy who worked binding books and learned science by reading the books he bound.", "Dams make energy without burning fuel, but they flood land and change life for rivers, animals and the people who live nearby."], ex: { t: "Water wheel", m: "a cardboard or foam plate, small paper or plastic cups, a pencil, tape, a faucet or jug of water", p: ["Tape the cups around the edge of the plate, all facing the same way, like the paddles of a wheel.", "Push the pencil through the center of the plate as an axle and hold it by the ends.", "Pour water onto the cups: the wheel spins! In power plants, that force turns a generator and becomes electricity."] }, at: "From water to light", m: "paper, colored pencils", p: ["Draw a river, a dam, a spinning turbine and wires coming out of the plant.", "Draw the wires reaching your house and lighting a bulb.", "Color the 13th bulb on your chart."], q: "Why do you think we should save energy, even when it comes from water?" },
es: { h: "En un viaje en auto, pasaron cerca de una represa enorme, con agua cayendo con fuerza. “Es una central hidroeléctrica”, contó el abuelo. “Casi toda la electricidad de nuestra casa empieza así: con agua haciendo girar una rueda gigante.” Leo abrió grandes los ojos: “¿El agua se convierte en luz?”", t: "De dónde viene la electricidad", f: "En 1831, Michael Faraday descubrió que, cuando un imán gira cerca de un cable enrollado, aparece electricidad en el cable. Así funciona un generador. En las centrales hidroeléctricas, el agua de un río represado hace girar turbinas, que hacen girar generadores enormes.", x: "¡La central de Itaipú, en el río Paraná, entre Brasil y Paraguay, es una de las que más energía producen en el mundo! La mayor parte de la electricidad de Brasil viene de la fuerza del agua.", s: ["Hay otras formas de hacer girar generadores: con vapor, con viento o con el movimiento de las mareas.", "Faraday era un niño pobre que trabajaba encuadernando libros y aprendió ciencia leyendo los libros que encuadernaba.", "Las represas producen energía sin quemar combustible, pero inundan tierras y cambian la vida de los ríos, los animales y las personas que viven cerca."], ex: { t: "Rueda de agua", m: "un plato de cartón o telgopor, vasitos de papel o plástico, un lápiz, cinta, una canilla o jarra de agua", p: ["Pega los vasitos alrededor del borde del plato, todos mirando hacia el mismo lado, como las paletas de una rueda.", "Atraviesa el centro del plato con el lápiz, como un eje, y sostenlo por las puntas.", "Echa agua sobre los vasitos: ¡la rueda gira! En las centrales, esa fuerza hace girar un generador y se convierte en electricidad."] }, at: "Del agua a la luz", m: "papel, lápices de colores", p: ["Dibuja un río, una represa, una turbina girando y cables saliendo de la central.", "Dibuja los cables llegando a tu casa y encendiendo una bombilla.", "Pinta la bombilla 13 del panel."], q: "¿Por qué crees que hay que ahorrar energía, aunque venga del agua?" } },

{ e: "☀️", art: { b: "☀️", s: ["🌬️", "🔆", "🍕", "🌱"], c: ["#4E3A0B", "#E0A02C"] },
pt: { h: "Na estrada para o Nordeste, Nina contou dezenas de cata-ventos gigantes girando no alto dos morros. E no telhado de uma casa, viu placas azuis brilhando no sol. “São usinas de vento e de sol”, disse o vovô. “Energia limpa, que não acaba.”", t: "Energia do vento e do Sol", f: "As turbinas eólicas são cata-ventos gigantes: o vento gira as pás, e as pás giram um gerador. Os painéis solares fazem diferente: transformam a luz do Sol diretamente em eletricidade, sem nenhuma peça se mexendo.", x: "O Nordeste do Brasil tem alguns dos melhores ventos do mundo para gerar energia, e cada vez mais casas brasileiras têm painéis solares no telhado!", s: ["A pá de uma turbina eólica grande pode ser mais comprida que um avião de passageiros médio.", "Os painéis solares funcionam até em dias nublados, mas produzem menos energia.", "Vento e sol são fontes renováveis: não acabam e quase não poluem."], ex: { t: "Forno solar de caixa de pizza", m: "uma caixa de pizza limpa, papel-alumínio, filme plástico, papel preto, fita, um biscoito com um pedaço de chocolate em cima, um dia de muito sol", p: ["Corte uma aba na tampa da caixa (com um adulto), forre a aba com alumínio e cubra a abertura com filme plástico.", "Forre o fundo da caixa com papel preto e coloque o biscoito com chocolate dentro.", "Deixe no sol forte com a aba virada para refletir a luz para dentro. Em meia hora ou mais, o chocolate derrete!"] }, at: "Cidade da energia limpa", m: "papel, lápis de cor", p: ["Desenhe uma cidade com turbinas de vento nos morros e painéis solares nos telhados.", "Desenhe as pessoas, as árvores e o céu limpinho.", "Pinte a 14ª lâmpada do painel."], q: "Que lugar da sua casa receberia mais sol para um painel solar?" },
en: { h: "On the road to Brazil's Northeast, Nina counted dozens of giant pinwheels turning on the hilltops. And on a house roof she saw blue panels shining in the sun. “They're wind and solar power plants,” Grandpa said. “Clean energy that doesn't run out.”", t: "Energy from wind and sun", f: "Wind turbines are giant pinwheels: the wind turns the blades, and the blades turn a generator. Solar panels work differently: they turn sunlight directly into electricity, with no moving parts.", x: "Brazil's Northeast has some of the best winds in the world for making energy, and more and more Brazilian homes have solar panels on their roofs!", s: ["A single blade of a big wind turbine can be longer than a medium-sized passenger plane.", "Solar panels work even on cloudy days, but they make less energy.", "Wind and sun are renewable sources: they don't run out and barely pollute."], ex: { t: "Pizza box solar oven", m: "a clean pizza box, aluminum foil, plastic wrap, black paper, tape, a cookie with a piece of chocolate on top, a very sunny day", p: ["Cut a flap in the lid of the box (with a grown-up), line the flap with foil and cover the opening with plastic wrap.", "Line the bottom of the box with black paper and put the cookie with chocolate inside.", "Leave it in strong sun with the flap angled to reflect light inside. In half an hour or more, the chocolate melts!"] }, at: "Clean energy city", m: "paper, colored pencils", p: ["Draw a city with wind turbines on the hills and solar panels on the roofs.", "Draw the people, the trees and a clean sky.", "Color the 14th bulb on your chart."], q: "Which spot at your house would get the most sun for a solar panel?" },
es: { h: "En la ruta hacia el Nordeste de Brasil, Nina contó decenas de molinos gigantes girando en lo alto de los cerros. Y en el techo de una casa vio placas azules brillando al sol. “Son centrales de viento y de sol”, dijo el abuelo. “Energía limpia, que no se acaba.”", t: "Energía del viento y del Sol", f: "Las turbinas eólicas son molinos gigantes: el viento hace girar las palas, y las palas hacen girar un generador. Los paneles solares funcionan distinto: transforman la luz del Sol directamente en electricidad, sin ninguna pieza que se mueva.", x: "¡El Nordeste de Brasil tiene algunos de los mejores vientos del mundo para generar energía, y cada vez más casas tienen paneles solares en el techo!", s: ["Una sola pala de una turbina eólica grande puede ser más larga que un avión de pasajeros mediano.", "Los paneles solares funcionan incluso en días nublados, pero producen menos energía.", "El viento y el sol son fuentes renovables: no se acaban y casi no contaminan."], ex: { t: "Horno solar de caja de pizza", m: "una caja de pizza limpia, papel de aluminio, film plástico, papel negro, cinta, una galletita con un pedazo de chocolate encima, un día de mucho sol", p: ["Corta una solapa en la tapa de la caja (con un adulto), fórrala con aluminio y cubre la abertura con film plástico.", "Forra el fondo de la caja con papel negro y pon adentro la galletita con chocolate.", "Déjala al sol fuerte con la solapa inclinada para reflejar la luz hacia adentro. ¡En media hora o más, el chocolate se derrite!"] }, at: "Ciudad de energía limpia", m: "papel, lápices de colores", p: ["Dibuja una ciudad con turbinas de viento en los cerros y paneles solares en los techos.", "Dibuja a las personas, los árboles y el cielo limpio.", "Pinta la bombilla 14 del panel."], q: "¿Qué lugar de tu casa recibiría más sol para un panel solar?" } },

{ e: "🗼", art: { b: "🗼", s: ["🐦", "🔌", "🏘️", "🪁"], c: ["#2A2A3A", "#6A6A8A"] },
pt: { h: "Leo viu vários passarinhos pousados num fio de luz na rua e ficou preocupado. “Eles vão levar choque!”, disse. O vovô explicou que eles estavam seguros. “Mas se uma pipa enroscar no fio, aí é perigosíssimo”, avisou. “Vou contar o porquê.”", t: "O caminho até a nossa casa", f: "A eletricidade sai das usinas e viaja por cabos enormes, presos em torres altas, às vezes por centenas de quilômetros. Ela viaja muito “forte”, com alta tensão, e perto das cidades passa por transformadores, que diminuem essa força antes de entrar nas casas.", x: "Os passarinhos não levam choque no fio porque encostam em um fio só e não tocam o chão. A eletricidade não tem para onde ir. Mas uma pessoa, ou uma pipa molhada que encosta no chão, cria um caminho, e isso é muito perigoso!", s: ["As linhas de transmissão podem levar eletricidade de uma usina no Norte até cidades no Sudeste do Brasil.", "Os transformadores são aquelas caixas cinzas que ficam no alto dos postes.", "Nunca solte pipa perto de fios e nunca tente pegar uma pipa enroscada: chame um adulto e a companhia de energia."], ex: { t: "Corrente de mãos", m: "a família ou um grupo de amigos, um relógio", p: ["Façam uma roda de mãos dadas.", "Uma pessoa aperta a mão do vizinho, que aperta a do próximo, e assim por diante, como um sinal passando.", "Cronometrem quanto tempo o “aperto” leva para dar a volta. Agora tentem mais rápido! A eletricidade passa pelos fios quase instantaneamente."] }, at: "Mapa da energia", m: "papel, lápis de cor", p: ["Desenhe a usina, as torres de transmissão, o transformador no poste e a sua casa.", "Desenhe passarinhos no fio e uma placa: “Pipa longe dos fios!”.", "Pinte a 15ª lâmpada do painel."], q: "Por que você acha que os fios das ruas ficam tão altos?" },
en: { h: "Leo saw several little birds perched on a power line in the street and got worried. “They're going to get shocked!” he said. Grandpa explained that they were safe. “But if a kite gets tangled in the line, that's extremely dangerous,” he warned. “I'll tell you why.”", t: "The journey to our homes", f: "Electricity leaves power plants and travels through huge cables strung on tall towers, sometimes for hundreds of kilometers. It travels very “strong,” at high voltage, and near cities it passes through transformers, which lower that strength before it enters homes.", x: "Birds don't get shocked on a power line because they touch only one wire and not the ground. The electricity has nowhere to go. But a person, or a damp kite string touching the ground, creates a path, and that's very dangerous!", s: ["Transmission lines can carry electricity from a power plant in Brazil's North all the way to cities in the Southeast.", "Transformers are often the gray boxes or cans up on utility poles.", "Never fly a kite near power lines and never try to grab a tangled kite: call a grown-up and the power company."], ex: { t: "Hand-squeeze chain", m: "your family or a group of friends, a clock", p: ["Stand in a circle holding hands.", "One person squeezes their neighbor's hand, who squeezes the next, and so on, like a signal passing along.", "Time how long the “squeeze” takes to go all the way around. Now try faster! Electricity moves through wires almost instantly."] }, at: "Energy map", m: "paper, colored pencils", p: ["Draw the power plant, the transmission towers, the transformer on the pole and your house.", "Draw birds on the wire and a sign: “Keep kites away from power lines!”", "Color the 15th bulb on your chart."], q: "Why do you think the wires along the street are so high up?" },
es: { h: "Leo vio varios pajaritos posados en un cable de luz en la calle y se preocupó. “¡Les va a dar una descarga!”, dijo. El abuelo explicó que estaban seguros. “Pero si un barrilete se enreda en el cable, eso sí es peligrosísimo”, advirtió. “Les voy a contar por qué.”", t: "El camino hasta nuestra casa", f: "La electricidad sale de las centrales y viaja por cables enormes, sostenidos en torres altas, a veces durante cientos de kilómetros. Viaja muy “fuerte”, con alta tensión, y cerca de las ciudades pasa por transformadores, que bajan esa fuerza antes de entrar en las casas.", x: "¡Los pajaritos no reciben descargas en el cable porque tocan un solo cable y no tocan el suelo. La electricidad no tiene adónde ir. Pero una persona, o el hilo húmedo de un barrilete que toca el suelo, crea un camino, y eso es muy peligroso!", s: ["Las líneas de transmisión pueden llevar electricidad desde una central en el norte de Brasil hasta ciudades del sudeste.", "Los transformadores suelen ser esas cajas grises que están arriba de los postes.", "Nunca remontes un barrilete cerca de cables y nunca intentes agarrar uno enredado: llama a un adulto y a la compañía de electricidad."], ex: { t: "Cadena de manos", m: "la familia o un grupo de amigos, un reloj", p: ["Hagan una ronda tomados de las manos.", "Una persona aprieta la mano del vecino, que aprieta la del siguiente, y así, como una señal que pasa.", "Cronometren cuánto tarda el “apretón” en dar la vuelta. ¡Ahora inténtenlo más rápido! La electricidad pasa por los cables casi al instante."] }, at: "Mapa de la energía", m: "papel, lápices de colores", p: ["Dibuja la central, las torres de transmisión, el transformador en el poste y tu casa.", "Dibuja pajaritos en el cable y un cartel: “¡Barriletes lejos de los cables!”.", "Pinta la bombilla 15 del panel."], q: "¿Por qué crees que los cables de la calle están tan altos?" } },

{ e: "⚠️", art: { b: "⚠️", s: ["🔌", "💧", "🚿", "🧯"], c: ["#5A2A0B", "#E0702C"] },
pt: { h: "Leo estava com as mãos molhadas do banho e foi ligar o secador de cabelo. O vovô segurou o braço dele na hora. “Espera! Primeiro seca bem as mãos”, disse. Depois, os três fizeram uma inspeção pela casa inteira, como detetives da segurança.", t: "Segurança com a eletricidade", f: "A eletricidade da tomada é muito útil, mas pode machucar muito. Por isso existem regras importantes: nunca mexer em tomadas, nunca usar aparelhos com as mãos ou os pés molhados, não puxar os fios pelo cabo e não ligar muitos aparelhos no mesmo benjamim.", x: "O chuveiro elétrico, muito comum no Brasil, esquenta a água com uma resistência elétrica. Por isso só um eletricista ou um adulto deve mexer nele, e sempre com o disjuntor desligado!", s: ["Os protetores de tomada evitam que crianças pequenas coloquem objetos nos buracos.", "O disjuntor, no quadro de luz, desliga a eletricidade sozinho quando há um problema.", "Fios descascados, tomadas quentes ou cheiro de queimado são sinais para chamar um adulto na hora."], ex: { t: "Detetives da segurança", m: "papel, lápis, um adulto", p: ["Com um adulto, percorra a casa olhando tomadas, fios e aparelhos, sem mexer em nada.", "Anote se encontrar: fios descascados, benjamins cheios demais, tomadas sem protetor perto do chão, aparelhos perto da água.", "Mostre a lista para os adultos e combinem juntos como resolver cada item."] }, at: "Cartaz das regras de ouro", m: "cartolina, lápis de cor", p: ["Escreva 5 regras de ouro da eletricidade, como “mãos secas sempre”.", "Desenhe um ícone para cada regra.", "Pendure num lugar visível e pinte a 16ª lâmpada do painel."], q: "Qual regra de segurança você acha mais importante ensinar para uma criança menor?" },
en: { h: "Leo's hands were still wet from his bath when he went to turn on the hair dryer. Grandpa caught his arm right away. “Wait! Dry your hands well first,” he said. Then the three of them inspected the whole house, like safety detectives.", t: "Electrical safety", f: "Outlet electricity is very useful, but it can cause serious harm. That's why there are important rules: never play with outlets, never use devices with wet hands or feet, don't pull plugs out by the cord and don't plug too many devices into one adapter or power strip.", x: "Electric showerheads, very common in Brazil, heat water with an electric heating element. That's why only an electrician or a grown-up should touch one, and always with the breaker switched off!", s: ["Outlet covers keep small children from poking objects into the holes.", "The circuit breaker, in the electrical panel, cuts the power by itself when there's a problem.", "Frayed wires, hot outlets or a burning smell are signs to call a grown-up right away."], ex: { t: "Safety detectives", m: "paper, pencil, a grown-up", p: ["With a grown-up, walk through the house looking at outlets, cords and devices, without touching anything.", "Write down anything you find: frayed cords, overloaded power strips, uncovered outlets near the floor, devices near water.", "Show the list to the grown-ups and decide together how to fix each item."] }, at: "Golden rules poster", m: "poster board, colored pencils", p: ["Write 5 golden rules of electricity, like “always dry hands.”", "Draw an icon for each rule.", "Hang it somewhere visible and color the 16th bulb on your chart."], q: "Which safety rule do you think is most important to teach a younger child?" },
es: { h: "Leo tenía las manos mojadas del baño y fue a encender el secador de pelo. El abuelo le agarró el brazo enseguida. “¡Espera! Primero sécate bien las manos”, dijo. Después, los tres hicieron una inspección por toda la casa, como detectives de la seguridad.", t: "Seguridad con la electricidad", f: "La electricidad del enchufe es muy útil, pero puede lastimar mucho. Por eso hay reglas importantes: nunca tocar los enchufes, nunca usar aparatos con las manos o los pies mojados, no desenchufar tirando del cable y no conectar muchos aparatos en el mismo adaptador o zapatilla.", x: "¡La ducha eléctrica, muy común en Brasil, calienta el agua con una resistencia eléctrica. Por eso solo un electricista o un adulto debe tocarla, y siempre con el disyuntor apagado!", s: ["Los protectores de enchufe evitan que los niños pequeños metan objetos en los agujeros.", "El disyuntor, en el tablero eléctrico, corta la electricidad solo cuando hay un problema.", "Cables pelados, enchufes calientes u olor a quemado son señales para llamar a un adulto enseguida."], ex: { t: "Detectives de la seguridad", m: "papel, lápiz, un adulto", p: ["Con un adulto, recorre la casa mirando enchufes, cables y aparatos, sin tocar nada.", "Anota si encuentras: cables pelados, zapatillas muy cargadas, enchufes sin protector cerca del piso, aparatos cerca del agua.", "Muestra la lista a los adultos y decidan juntos cómo resolver cada cosa."] }, at: "Cartel de las reglas de oro", m: "cartulina, lápices de colores", p: ["Escribe 5 reglas de oro de la electricidad, como “siempre manos secas”.", "Dibuja un ícono para cada regla.", "Cuélgalo en un lugar visible y pinta la bombilla 16 del panel."], q: "¿Qué regla de seguridad crees que es más importante enseñarle a un niño más chico?" } },

{ e: "⚙️", art: { b: "⚙️", s: ["🌀", "🧲", "🔋", "🚗"], c: ["#1B3A3A", "#3A8A8A"] },
pt: { h: "Leo desmontou um carrinho de pilha velho, com o vovô, e achou lá dentro uma pecinha redonda com fios. “Isso é o coração do carrinho”, disse o vovô. “É um motor elétrico. Ele transforma eletricidade em movimento.” Nina quis montar um também.", t: "O motor elétrico", f: "Um motor elétrico usa eletroímãs e ímãs que se empurram e se puxam, fazendo uma peça girar sem parar. Em 1821, Michael Faraday mostrou o primeiro motor elétrico simples. Hoje, motores estão em ventiladores, liquidificadores, máquinas de lavar, elevadores e carros elétricos.", x: "Uma casa comum pode ter dezenas de motores elétricos escondidos: no ventilador, na geladeira, no secador, no relógio e até na escova de dentes elétrica!", s: ["O motor faz o contrário do gerador: o gerador transforma movimento em eletricidade, e o motor transforma eletricidade em movimento.", "Os motores elétricos são silenciosos e não soltam fumaça.", "Os celulares têm um motorzinho minúsculo que faz o aparelho vibrar."], ex: { t: "Motor mais simples do mundo", m: "uma pilha AA, um ímã de neodímio redondo e chato, um parafuso de ferro, um pedaço de fio de cobre desencapado, um adulto", p: ["Atenção: ímãs de neodímio são muito fortes e perigosos se engolidos. Só um adulto mexe neles.", "O adulto gruda o ímã na cabeça do parafuso e pendura a ponta do parafuso no polo de baixo da pilha (o ímã segura tudo).", "O adulto encosta uma ponta do fio no polo de cima e a outra na lateral do ímã: o parafuso começa a girar! Faça só por alguns segundos."] }, at: "Caça aos motores", m: "papel, lápis", p: ["Com um adulto, descubra quais aparelhos da casa têm motor (dica: os que têm partes que giram ou vibram).", "Faça uma lista e desenhe cada um.", "Pinte a 17ª lâmpada do painel."], q: "Que coisa da sua casa seria mais difícil de fazer sem um motor elétrico?" },
en: { h: "Leo took apart an old battery-powered toy car with Grandpa and found a little round part with wires inside. “That's the car's heart,” said Grandpa. “It's an electric motor. It turns electricity into motion.” Nina wanted to build one too.", t: "The electric motor", f: "An electric motor uses electromagnets and magnets that push and pull on each other, making a part spin around and around. In 1821, Michael Faraday showed the first simple electric motor. Today motors are in fans, blenders, washing machines, elevators and electric cars.", x: "An ordinary home can have dozens of hidden electric motors: in the fan, the fridge, the hair dryer, clocks and even electric toothbrushes!", s: ["A motor does the opposite of a generator: a generator turns motion into electricity, and a motor turns electricity into motion.", "Electric motors are quiet and don't give off smoke.", "Phones have a teeny motor that makes them vibrate."], ex: { t: "The simplest motor in the world", m: "an AA battery, a flat round neodymium magnet, an iron screw, a piece of bare copper wire, a grown-up", p: ["Warning: neodymium magnets are very strong and dangerous if swallowed. Only a grown-up handles them.", "The grown-up sticks the magnet to the head of the screw and hangs the screw's tip from the bottom end of the battery (the magnet holds it all together).", "The grown-up touches one end of the wire to the top of the battery and the other to the side of the magnet: the screw starts spinning! Only do it for a few seconds."] }, at: "Motor hunt", m: "paper, pencil", p: ["With a grown-up, find out which devices at home have motors (hint: the ones with parts that spin or vibrate).", "Make a list and draw each one.", "Color the 17th bulb on your chart."], q: "What would be hardest to do at home without an electric motor?" },
es: { h: "Leo desarmó un autito a pilas viejo con el abuelo y encontró adentro una piecita redonda con cables. “Ese es el corazón del autito”, dijo el abuelo. “Es un motor eléctrico. Transforma la electricidad en movimiento.” Nina quiso armar uno también.", t: "El motor eléctrico", f: "Un motor eléctrico usa electroimanes e imanes que se empujan y se atraen, haciendo girar una pieza sin parar. En 1821, Michael Faraday mostró el primer motor eléctrico simple. Hoy hay motores en ventiladores, licuadoras, lavarropas, ascensores y autos eléctricos.", x: "¡Una casa común puede tener decenas de motores eléctricos escondidos: en el ventilador, en la heladera, en el secador, en los relojes y hasta en el cepillo de dientes eléctrico!", s: ["El motor hace lo contrario que el generador: el generador transforma movimiento en electricidad, y el motor transforma electricidad en movimiento.", "Los motores eléctricos son silenciosos y no largan humo.", "Los celulares tienen un motorcito diminuto que los hace vibrar."], ex: { t: "El motor más simple del mundo", m: "una pila AA, un imán de neodimio redondo y chato, un tornillo de hierro, un pedazo de cable de cobre pelado, un adulto", p: ["Atención: los imanes de neodimio son muy fuertes y peligrosos si se tragan. Solo un adulto los manipula.", "El adulto pega el imán a la cabeza del tornillo y cuelga la punta del tornillo del polo de abajo de la pila (el imán sostiene todo).", "El adulto toca con una punta del cable el polo de arriba y con la otra el costado del imán: ¡el tornillo empieza a girar! Hazlo solo unos segundos."] }, at: "Caza de motores", m: "papel, lápiz", p: ["Con un adulto, descubre qué aparatos de la casa tienen motor (pista: los que tienen partes que giran o vibran).", "Haz una lista y dibuja cada uno.", "Pinta la bombilla 17 del panel."], q: "¿Qué cosa de tu casa sería más difícil de hacer sin un motor eléctrico?" } },

{ e: "🚄", art: { b: "🚄", s: ["🔌", "🧲", "🚗", "🔋"], c: ["#0B3A2A", "#2CA06A"] },
pt: { h: "Um carro passou pela rua quase sem fazer barulho, e Leo achou que ele estava desligado. “É elétrico”, explicou o vovô. “E tem trem no mundo que nem encosta nos trilhos: flutua em cima de ímãs!” Nina e Leo correram buscar os ímãs da geladeira.", t: "Carros e trens elétricos", f: "Os carros elétricos usam baterias grandes e motores elétricos em vez de gasolina. Eles são silenciosos e não soltam fumaça pelo escapamento. Alguns trens, chamados maglev, flutuam sobre os trilhos usando ímãs poderosos e quase não têm atrito.", x: "Os carros elétricos não são uma invenção nova: por volta de 1900, uma boa parte dos carros nos Estados Unidos era elétrica, antes de os carros a gasolina dominarem!", s: ["O trem maglev de Xangai, na China, já chegou a mais de 400 quilômetros por hora.", "Muitos ônibus elétricos já circulam em cidades brasileiras.", "Os metrôs e muitos trens também são movidos a eletricidade."], ex: { t: "Carrinhos que se empurram", m: "dois carrinhos de brinquedo, dois ímãs, fita adesiva", p: ["Prenda um ímã na traseira de cada carrinho com fita.", "Aproxime os carrinhos de um jeito: eles se grudam. Vire um dos ímãs.", "Agora um carrinho empurra o outro sem encostar! Os trens maglev usam essa força para flutuar e andar."] }, at: "Estação do futuro", m: "papel, lápis de cor", p: ["Desenhe uma estação com um trem maglev flutuando e carros elétricos carregando na tomada.", "Invente um nome para a linha do trem e as paradas.", "Pinte a 18ª lâmpada do painel."], q: "Você prefere viajar de carro, de ônibus ou de trem? Por quê?" },
en: { h: "A car went down the street making almost no noise, and Leo thought it was turned off. “It's electric,” Grandpa explained. “And there are trains in the world that don't even touch their tracks: they float on magnets!” Nina and Leo ran to get the fridge magnets.", t: "Electric cars and trains", f: "Electric cars use big batteries and electric motors instead of gasoline. They're quiet and don't give off fumes from a tailpipe. Some trains, called maglevs, float above their tracks using powerful magnets and have almost no friction.", x: "Electric cars aren't a new invention: around 1900, a good share of cars in the United States were electric, before gasoline cars took over!", s: ["The Shanghai maglev train in China has reached more than 400 kilometers per hour (250 mph).", "Many electric buses already run in Brazilian cities.", "Subways and many trains also run on electricity."], ex: { t: "Cars that push each other", m: "two toy cars, two magnets, tape", p: ["Tape a magnet to the back of each car.", "Bring the cars together one way: they stick. Flip one magnet around.", "Now one car pushes the other without touching! Maglev trains use this force to float and move."] }, at: "Station of the future", m: "paper, colored pencils", p: ["Draw a station with a floating maglev train and electric cars charging.", "Invent a name for the train line and its stops.", "Color the 18th bulb on your chart."], q: "Do you prefer traveling by car, bus or train? Why?" },
es: { h: "Un auto pasó por la calle casi sin hacer ruido, y Leo pensó que estaba apagado. “Es eléctrico”, explicó el abuelo. “¡Y hay trenes en el mundo que ni tocan las vías: flotan sobre imanes!” Nina y Leo corrieron a buscar los imanes de la heladera.", t: "Autos y trenes eléctricos", f: "Los autos eléctricos usan baterías grandes y motores eléctricos en vez de nafta. Son silenciosos y no largan humo por el caño de escape. Algunos trenes, llamados maglev, flotan sobre las vías usando imanes poderosos y casi no tienen fricción.", x: "¡Los autos eléctricos no son un invento nuevo: alrededor de 1900, una buena parte de los autos en Estados Unidos era eléctrica, antes de que dominaran los autos a nafta!", s: ["El tren maglev de Shanghái, en China, llegó a superar los 400 kilómetros por hora.", "Muchos autobuses eléctricos ya circulan en ciudades de América Latina.", "Los subtes y muchos trenes también funcionan con electricidad."], ex: { t: "Autitos que se empujan", m: "dos autitos de juguete, dos imanes, cinta adhesiva", p: ["Pega un imán en la parte de atrás de cada autito con cinta.", "Acerca los autitos de una forma: se pegan. Da vuelta uno de los imanes.", "¡Ahora un autito empuja al otro sin tocarlo! Los trenes maglev usan esa fuerza para flotar y moverse."] }, at: "Estación del futuro", m: "papel, lápices de colores", p: ["Dibuja una estación con un tren maglev flotando y autos eléctricos cargándose.", "Inventa un nombre para la línea del tren y sus paradas.", "Pinta la bombilla 18 del panel."], q: "¿Prefieres viajar en auto, en autobús o en tren? ¿Por qué?" } },

{ e: "📟", art: { b: "📟", s: ["🔦", "📜", "⚡", "🌳"], c: ["#3A2A1B", "#8A6A3A"] },
pt: { h: "Na hora de dormir, Nina e Leo combinaram de conversar de um quarto para o outro piscando a lanterna. Um piscar curto, um comprido… O vovô espiou e riu: “Vocês reinventaram o código Morse! Foi assim que as primeiras mensagens elétricas atravessaram o mundo.”", t: "O telégrafo e o código Morse", f: "Em 1844, o americano Samuel Morse enviou uma mensagem pelo telégrafo entre duas cidades dos Estados Unidos. O telégrafo mandava pulsos elétricos curtos e longos por um fio. Cada letra virava uma combinação de pontos e traços: o código Morse.", x: "No Brasil, o marechal Cândido Rondon liderou expedições que levaram linhas de telégrafo pelo meio da floresta até a Amazônia, no começo dos anos 1900!", s: ["O pedido de socorro mais famoso do mundo, SOS, em Morse é: três pontos, três traços, três pontos.", "Em 1866, um cabo de telégrafo no fundo do mar passou a ligar a Europa e a América.", "Antes do telégrafo, uma notícia podia levar semanas para cruzar o oceano. Depois, levava minutos."], ex: { t: "Mensagens de luz", m: "duas lanternas, uma tabela do código Morse (procure com um adulto), papel", p: ["Combinem: uma piscada rápida é um ponto, uma piscada longa é um traço.", "Uma pessoa manda uma palavra curta, como “OI” ou “SOS”, piscando a lanterna num quarto escuro.", "A outra anota os pontos e traços e descobre a palavra com a tabela."] }, at: "Meu nome em Morse", m: "papel, lápis de cor", p: ["Escreva seu nome em Morse, com bolinhas e tracinhos.", "Faça um colar ou pulseira de papel com contas redondas (pontos) e compridas (traços).", "Pinte a 19ª lâmpada do painel."], q: "Que mensagem curtinha você mandaria para alguém do outro lado do mundo?" },
en: { h: "At bedtime, Nina and Leo agreed to talk from one room to the other by flashing a flashlight. A short flash, a long one… Grandpa peeked in and laughed: “You've reinvented Morse code! That's how the first electric messages crossed the world.”", t: "The telegraph and Morse code", f: "In 1844, American Samuel Morse sent a message by telegraph between two U.S. cities. The telegraph sent short and long electric pulses along a wire. Each letter became a combination of dots and dashes: Morse code.", x: "In Brazil, Marshal Cândido Rondon led expeditions that strung telegraph lines through the middle of the forest all the way to the Amazon, in the early 1900s!", s: ["The world's most famous distress call, SOS, in Morse is: three dots, three dashes, three dots.", "In 1866, an undersea telegraph cable began connecting Europe and America.", "Before the telegraph, news could take weeks to cross the ocean. Afterward, it took minutes."], ex: { t: "Light messages", m: "two flashlights, a Morse code chart (look one up with a grown-up), paper", p: ["Agree: a quick flash is a dot and a long flash is a dash.", "One person sends a short word, like “HI” or “SOS,” by flashing the light in a dark room.", "The other writes down the dots and dashes and decodes the word with the chart."] }, at: "My name in Morse", m: "paper, colored pencils", p: ["Write your name in Morse code with dots and dashes.", "Make a paper necklace or bracelet with round beads (dots) and long beads (dashes).", "Color the 19th bulb on your chart."], q: "What short message would you send to someone on the other side of the world?" },
es: { h: "A la hora de dormir, Nina y Leo acordaron hablar de un cuarto al otro haciendo parpadear la linterna. Un destello corto, uno largo… El abuelo se asomó y se rió: “¡Reinventaron el código Morse! Así cruzaron el mundo los primeros mensajes eléctricos.”", t: "El telégrafo y el código Morse", f: "En 1844, el estadounidense Samuel Morse envió un mensaje por telégrafo entre dos ciudades de Estados Unidos. El telégrafo mandaba pulsos eléctricos cortos y largos por un cable. Cada letra se convertía en una combinación de puntos y rayas: el código Morse.", x: "¡En Brasil, el mariscal Cândido Rondon dirigió expediciones que llevaron líneas de telégrafo por el medio de la selva hasta la Amazonía, a principios del siglo XX!", s: ["El pedido de auxilio más famoso del mundo, SOS, en Morse es: tres puntos, tres rayas, tres puntos.", "En 1866, un cable de telégrafo en el fondo del mar empezó a unir Europa y América.", "Antes del telégrafo, una noticia podía tardar semanas en cruzar el océano. Después, tardaba minutos."], ex: { t: "Mensajes de luz", m: "dos linternas, una tabla del código Morse (búscala con un adulto), papel", p: ["Acuerden: un destello rápido es un punto y uno largo es una raya.", "Una persona manda una palabra corta, como “HOLA” o “SOS”, con la linterna en un cuarto oscuro.", "La otra anota los puntos y rayas y descubre la palabra con la tabla."] }, at: "Mi nombre en Morse", m: "papel, lápices de colores", p: ["Escribe tu nombre en Morse, con puntitos y rayitas.", "Haz un collar o pulsera de papel con cuentas redondas (puntos) y alargadas (rayas).", "Pinta la bombilla 19 del panel."], q: "¿Qué mensaje cortito le mandarías a alguien del otro lado del mundo?" } },

{ e: "📻", art: { b: "📻", s: ["〰️", "📡", "⛪", "🎶"], c: ["#2A1B3A", "#7A4A9A"] },
pt: { h: "O vovô ligou um radinho antigo e girou o botão. Primeiro chiado, depois uma música, depois um jogo de futebol. “De onde vem essa voz?”, perguntou Leo, olhando atrás do rádio. “De muito longe, viajando pelo ar em ondas invisíveis”, disse o vovô. “E um padre brasileiro foi um dos primeiros a fazer isso!”", t: "O rádio e as ondas invisíveis", f: "O rádio usa ondas eletromagnéticas, que viajam pelo ar sem precisar de fios. Por volta de 1900, o italiano Guglielmo Marconi transmitiu sinais de rádio a grandes distâncias. No Brasil, o padre gaúcho Roberto Landell de Moura transmitiu a voz humana por ondas de rádio em São Paulo, mais ou menos na mesma época.", x: "As ondas de rádio viajam à velocidade da luz: dariam mais de sete voltas na Terra em um segundo!", s: ["Landell de Moura registrou patentes no Brasil e nos Estados Unidos, mas na época poucas pessoas deram atenção às suas invenções.", "O wi-fi, o celular, o GPS e o controle remoto do portão também usam ondas invisíveis.", "As ondas de rádio são parentes da luz, só que nossos olhos não conseguem vê-las."], ex: { t: "Ondas na bacia", m: "uma bacia com água, uma pedrinha ou gotas de um conta-gotas, uma corda de pular", p: ["Pingue uma gota no meio da bacia de água parada e observe os círculos se espalhando.", "Agora amarre a corda num pé de mesa e balance a outra ponta para cima e para baixo: aparecem ondas viajando.", "As ondas de rádio também se espalham assim, só que pelo ar, de forma invisível e rapidíssima!"] }, at: "Minha rádio", m: "uma caixinha, papel, lápis de cor, um celular para gravar (opcional)", p: ["Monte um “rádio” com uma caixinha e desenhe botões e uma antena.", "Invente o nome da sua rádio e grave ou apresente um programa: notícias da família, uma música e uma previsão do tempo.", "Pinte a 20ª lâmpada do painel."], q: "Se você tivesse um programa de rádio, sobre o que falaria?" },
en: { h: "Grandpa turned on an old little radio and turned the dial. First static, then music, then a soccer game. “Where does that voice come from?” Leo asked, looking behind the radio. “From very far away, traveling through the air in invisible waves,” Grandpa said. “And a Brazilian priest was one of the first to do it!”", t: "Radio and invisible waves", f: "Radio uses electromagnetic waves, which travel through the air without wires. Around 1900, Italian Guglielmo Marconi sent radio signals over long distances. In Brazil, Father Roberto Landell de Moura, from Rio Grande do Sul, transmitted the human voice by radio waves in São Paulo at about the same time.", x: "Radio waves travel at the speed of light: they could go around the Earth more than seven times in one second!", s: ["Landell de Moura registered patents in Brazil and the United States, but at the time few people paid attention to his inventions.", "Wi-Fi, cell phones, GPS and garage door remotes also use invisible waves.", "Radio waves are relatives of light; our eyes just can't see them."], ex: { t: "Waves in a basin", m: "a basin of water, a pebble or drops from a dropper, a jump rope", p: ["Drip a drop into the middle of the still water and watch the circles spread out.", "Now tie the rope to a table leg and shake the other end up and down: waves travel along it.", "Radio waves spread out like this too, only through the air, invisibly and incredibly fast!"] }, at: "My radio station", m: "a small box, paper, colored pencils, a phone to record (optional)", p: ["Make a “radio” from a small box and draw buttons and an antenna.", "Name your station and record or perform a show: family news, a song and a weather forecast.", "Color the 20th bulb on your chart."], q: "If you had a radio show, what would you talk about?" },
es: { h: "El abuelo encendió una radio vieja y giró la perilla. Primero ruido, después una canción, después un partido de fútbol. “¿De dónde viene esa voz?”, preguntó Leo, mirando detrás de la radio. “De muy lejos, viajando por el aire en ondas invisibles”, dijo el abuelo. “¡Y un sacerdote brasileño fue uno de los primeros en hacerlo!”", t: "La radio y las ondas invisibles", f: "La radio usa ondas electromagnéticas, que viajan por el aire sin necesidad de cables. Alrededor de 1900, el italiano Guglielmo Marconi transmitió señales de radio a grandes distancias. En Brasil, el padre Roberto Landell de Moura, de Rio Grande do Sul, transmitió la voz humana por ondas de radio en São Paulo más o menos en la misma época.", x: "¡Las ondas de radio viajan a la velocidad de la luz: darían más de siete vueltas a la Tierra en un segundo!", s: ["Landell de Moura registró patentes en Brasil y en Estados Unidos, pero en su época pocas personas prestaron atención a sus inventos.", "El wifi, el celular, el GPS y el control remoto del portón también usan ondas invisibles.", "Las ondas de radio son parientes de la luz, solo que nuestros ojos no pueden verlas."], ex: { t: "Ondas en la palangana", m: "una palangana con agua, una piedrita o gotas de un gotero, una soga de saltar", p: ["Deja caer una gota en el medio del agua quieta y mira cómo se esparcen los círculos.", "Ahora ata la soga a la pata de una mesa y mueve la otra punta hacia arriba y hacia abajo: aparecen ondas que viajan.", "¡Las ondas de radio también se esparcen así, solo que por el aire, de forma invisible y rapidísima!"] }, at: "Mi radio", m: "una cajita, papel, lápices de colores, un celular para grabar (opcional)", p: ["Arma una “radio” con una cajita y dibuja botones y una antena.", "Inventa el nombre de tu radio y graba o presenta un programa: noticias de la familia, una canción y el pronóstico del tiempo.", "Pinta la bombilla 20 del panel."], q: "Si tuvieras un programa de radio, ¿de qué hablarías?" } },
];
